/* Boutons */
.primary-button {
    background-color: #f9f9f9 !important;
    color: #513018 !important;
    border: 1px solid #2d2b1e !important;
    border-radius: 50px !important;    /* Boutons arrondis */
    padding: 10px 20px;                /* Espacement interne */
    font-family: "Open Sans", sans-serif;
    font-size: 16px;
    font-weight: 700;
    text-transform: uppercase;         /* Texte en majuscules */
    transition: all 0.3s ease-in-out;
}

.primary-button:hover {
    background-color: #b19067 !important;
    color: #fefafa !important;
    border: 1px solid #b19067 !important;
}

/* Titres */
h1, h2, h3, .card-title {
    color: #513018;                      /* Couleur principale */
    text-transform: uppercase;           /* Texte en majuscules */
    font-size: 20px;                     /* Taille standard des titres */
    font-family: "Be Vietnam Pro", sans-serif;
    font-weight: 700;
    font-style: normal;
}

/* Paragraphe ou texte de la carte */
p, .card-text {
    color: #513018;                      /* Couleur principale */
    font-family: "Open Sans", sans-serif;
    font-optical-sizing: auto;
    font-weight: 400;
    font-style: normal;
    line-height: 1.6;                    /* Espacement entre les lignes */
}

/* Style des cartes */
.card {
    border: none;                        /* Retire les bordures par défaut */
    box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1); /* Ombre discrète */
    border-radius: 15px;                 /* Coins arrondis */
    transition: all 0.3s ease-in-out;
}

.card:hover {
    transform: scale(1.03);              /* Animation de zoom au survol */
}

/* Conteneur interne des cartes */
.card-body {
    padding: 20px;                       /* Espacement interne */
}

/* Section globale des cartes */
.cards-section {
    padding: 40px;
    background-color: #fefafa;           /* Couleur d'arrière-plan douce */
    border-radius: 20px;
}

/* Titre de la section */
.methods-title {
    text-align: center;
    margin-bottom: 30px;
    font-size: 28px;
    font-weight: bold;
    color: #513018;
    margin-bottom: 60px;
}

/* Images dans les cartes */
.card img {
    border-top-left-radius: 15px;        /* Arrondi des coins de l'image */
    border-top-right-radius: 15px;
    width: 100%;                         /* Image responsive */
    height: auto;
    object-fit: cover;                   /* Ajuste l'image pour remplir l'espace */
}

